    	    			 name: IdOrOpOrAnonymousName,
                                 triples: List[(ArrowType,Option[Int],Option[JavaFunctional])],
                                 isMethod: Boolean,
                             oa: OverloadingOracle): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      if (fsp != gsp || (isMethod && fsp.isEmpty)) false
      else {
        val hs = signatures.collect {
          case (ha, hsp, _) if hsp == fsp && !(ha eq fa) && !(ha eq ga) &&
